  "auth.aboutLink": "Luminous StockHaven વિશે",
  'about.bookshopLeadIn': "અમારી પુસ્તકોની દુકાન ચલાવતા એ જ નાના વ્યવસાય દ્વારા બનાવેલ:",
  "about.eyebrow": "Luminous StockHaven વિશે",
  "about.pageTitle": "Luminous StockHaven — અમારા વિશે",
  "about.founderHeading": "📖 સ્થાપક વિશે",
  "about.founder.p1": "નમસ્તે, હું કોન્સેપ્સિયોન છું, Luminous StockHaven ની સ્થાપક.",
  "about.founder.p2": "હું કોઈ મોટી ટેક કંપનીમાંથી આવી નથી, અને હું કોઈ કોર્પોરેટ ઓફિસમાં બેસતી નથી. હું એક નાની છૂટક વેપારી છું, બિલકુલ તમારા જેવી જ. હું પાંચ ઈ-કોમર્સ દુકાનો ચલાવું છું, જે પુસ્તકો અને પુસ્તક-પ્રેમીઓ માટે હાથથી બનાવેલી વસ્તુઓમાં વિશેષતા ધરાવે છે.\nઘણા સ્વતંત્ર છૂટક વેપારીઓની જેમ, હું એક તૂટવાના બિંદુએ પહોંચી ગઈ હતી જ્યારે હું અનેક સ્થળોની ઈન્વેન્ટરી સંભાળવા, પ્રકાશકોના ISBN ને મારા પોતાના હાથથી બનાવેલા SKU સાથે ટ્રેક કરવા, અને અણઘડ સ્પ્રેડશીટથી સપ્લાયર ઓર્ડર સંભાળવાનો પ્રયાસ કરતી હતી. જ્યારે મેં મદદ માટે એપ શોધી, ત્યારે મેં છ અલગ વિકલ્પો અજમાવ્યા. દરેક કાં તો સંપૂર્ણપણે અધૂરો હતો, કાં અવિશ્વસનીય રીતે ગૂંચવણભર્યો હતો, કાં લૂંટારો હતો — મૂળભૂત સાધનો માટે મહિને સેંકડો ડોલર વસૂલતા હતા.",
  "about.founder.p3": "સ્વતંત્ર સર્જકોનું શોષણ કરતા ઉદ્યોગથી નિરાશ થઈને, મેં મારો પોતાનો ઉકેલ બનાવવાનું નક્કી કર્યું. મેં Luminous StockHaven જરૂરિયાતમાંથી બનાવ્યું, જેથી હું મારા પોતાના વ્યવસાયો સ્વચ્છ રીતે, કાર્યક્ષમ રીતે અને સંપૂર્ણ માનસિક શાંતિથી ચલાવી શકું.",
  "about.founder.p4": "મેં આ પ્લેટફોર્મને પ્રામાણિક, પોસાય તેવી કિંમતે જાહેર જનતા માટે ખોલવાનું નક્કી કર્યું, કારણ કે દરેક નાનો વેપારી એવા સાધનોનો હકદાર છે જે ખરેખર કામ કરે, તેની કમાણીને જોખમમાં મૂક્યા વિના. અમે સ્વતંત્ર રીતે માલિકી ધરાવીએ છીએ, અમારા સમુદાયનું ઉગ્રતાથી રક્ષણ કરીએ છીએ, અને એક છૂટક વેપારી દ્વારા, છૂટક વેપારીઓ માટે બનાવવામાં આવ્યા છીએ.",
  "notice.ariaLabel": "ટ્રેડમાર્ક અને કોપીરાઈટ સૂચના",
  "notice.heading": "🛡️ છૂટક વેપારીઓ માટે બનાવ્યું, કોર્પોરેટ ગીધો માટે અમૂલ્ય",
  "notice.intro": "મેં આ એપ બનાવી કારણ કે હું 5 દુકાનો ચલાવું છું અને સેંકડો ડોલરના ગૂંચવણભર્યા સોફ્ટવેરથી છેતરાઈને થાકી ગઈ હતી. આ એપ સ્વતંત્ર કલાકારો, કારીગરો, પુસ્તક વિક્રેતાઓ અને સ્થાનિક દુકાનોનું રક્ષણ કરવા માટે બનાવવામાં આવી હતી.",
  "notice.legalHeading": "સ્પર્ધકો અને નકલ કરનારાઓ માટે કાનૂની સૂચના:",
  "notice.legalBody": "અમે બજાર પર સક્રિય રીતે નજર રાખીએ છીએ. અમારા પ્લેટફોર્મનો ડેટા કાઢવાનો, અમારી માલિકીની કાર્યપદ્ધતિઓની નકલ કરવાનો, અથવા અમારી બૌદ્ધિક સંપત્તિનું ઉલ્લંઘન કરવાનો કોઈપણ પ્રયાસ તાત્કાલિક અને આક્રમક કાનૂની કાર્યવાહીનો સામનો કરશે.",
  "notice.acquisitionHeading": "અધિગ્રહણ કંપનીઓ અને દલાલો માટે:",
  "notice.acquisitionBody": "મને ઈમેલ ન કરો. મને સંદેશ ન મોકલો. મને 'વ્યૂહાત્મક બહાર નીકળવું' સૂચવશો નહીં. તમે હજારો, લાખો, કરોડો કે અબજો ઓફર કરી શકો છો — જવાબ છે ના. તમે આ એપ ફક્ત મારા સાથી વેપારીઓ માટે ભાવ વધારવા માટે ખરીદશો નહીં. દરેક અવાંછિત અધિગ્રહણ ઈમેલ તરત જ સ્પામ તરીકે ચિહ્નિત થશે, અને તમારું ડોમેન અમારા પ્લેટફોર્મ પરથી કાયમી રીતે અવરોધિત થશે. તમારી મહેનત બચાવો.",
  "footer.trademarkLine": "અનધિકૃત નકલ, ક્લોનિંગ અથવા ડેટા કાઢવો સખત પ્રતિબંધિત છે.",
