  "welcome.noTrialNote": "આ સ્ક્રીન ખોલવાથી કંઈ શરૂ થતું નથી. કોઈ ટ્રાયલ શરૂ થતી નથી અને કોઈ કાર્ડ ચાર્જ થતું નથી — સાત દિવસની ટ્રાયલ ત્યારે જ શરૂ થાય છે જ્યારે તમે પ્લાન પસંદ કરીને તેની પુષ્ટિ કરો. બંને વેબસાઇટ પ્લાનમાં મોબાઇલ સાથી સામેલ છે, તેથી તમે તેના પર ક્યારેય વધારાની માસિક મોબાઇલ ફી ચૂકવતા નથી.",
  "welcome.alreadyHaveAccount": "પહેલેથી StockHaven એકાઉન્ટ છે?",
  "welcome.signIn": "સાઇન ઇન",
  "welcome.inventoryWaiting": "અને તમારી ઇન્વેન્ટરી તમે જ્યાં છોડી હતી ત્યાં જ છે.",
  "thankYou.unverified.notVerified": "Stripe એ આ ચેકઆઉટ સેટ કરવાનું હજુ પૂરું કર્યું નથી. તમારું પેમેન્ટ સુરક્ષિત છે — કંઈ બે વાર ચાર્જ થયું નથી. અમે તપાસતા રહીશું.",
  "thankYou.unverified.trialNotEligible": "આ ઈમેઈલે તેની એક મફત ટ્રાયલ પહેલેથી વાપરી લીધી છે, તેથી ટ્રાયલ શરૂ થઈ શકી નહીં. જો તમને લાગે કે આ ભૂલ છે તો સપોર્ટનો સંપર્ક કરો.",
  "thankYou.unverified.noPendingCheckout": "આ વર્કસ્પેસ માટે અમને કોઈ બાકી ચેકઆઉટ મળ્યું નથી.",
  "thankYou.unverified.default": "તમારી ખરીદી હજુ ચકાસાઈ નથી. અમે તપાસતા રહીશું — બીજું ચેકઆઉટ શરૂ કરશો નહીં.",
  "thankYou.grantedTitle": "તમે અંદર છો — તમારા પ્લાનમાં સ્વાગત છે.",
  "thankYou.trialRunning": "તમારી 7-દિવસની મફત ટ્રાયલ {date} સુધી ચાલુ છે. ટ્રાયલ પૂરી થાય ત્યાં સુધી તમને ચાર્જ થશે નહીં.",
