  "thankYou.pendingTitle": "તમારી ખરીદી હજુ ચકાસાઈ નથી.",
  "thankYou.checkingBody": "અમે Stripe સાથે તમારું સબસ્ક્રિપ્શન ચકાસી રહ્યા છીએ. આમાં સામાન્ય રીતે થોડી સેકન્ડ લાગે છે — કૃપા કરીને આ પેજ ખુલ્લું રાખો.",
