  "upgrade.upgradeNote": "તે જ સબસ્ક્રિપ્શન, બીજી ટ્રાયલ નહીં, તાત્કાલિક ચાર્જ નહીં — કિંમતનો તફાવત તમારા આગલા ઇન્વોઇસ પર આવશે.",
