  "settings.footer.note": "આ સેટિંગ્સ ફક્ત આ વ્યવસાયની છે. તમારી માલિકીનો દરેક વ્યવસાય તેની પોતાની પ્રોડક્ટ, લોકેશન, સપ્લાયર અને ખરીદી ઓર્ડર રાખે છે — તેમની વચ્ચે જવા વ્યવસાય સ્વિચર વાપરો.",
