  "settings.pastDue.body": "તમારી છેલ્લી ચુકવણી પૂર્ણ થઈ નથી. નિષ્ફળ ચુકવણીથી 14 દિવસ સુધી તમને સંપૂર્ણ ઉપયોગ મળતો રહે છે, જ્યાં સુધી તમે તેને સુધારો છો. જો તે સુધરે નહીં, તો સબ્સ્ક્રિપ્શન રદ થઈ જશે, વર્કસ્પેસ 15 દિવસ માટે ફક્ત જોવા યોગ્ય રહેશે, અને પછી ખાતું અને તેની બધી માહિતી કાઢી નાખવામાં આવશે. કાઢી નાખતા પહેલાં કોઈપણ સમયે ચુકવણી કરવાથી બધું પાછું આવે છે. જો તમને ખાતરી ન હોય કે શું કરવું, તો theluminousbookshop@outlook.com પર સહાયનો સંપર્ક કરો।",
