  "workforce.inbox.help": "તમારી ટીમ માટે ક્લોક ઘટનાઓ, રજાના જવાબ, કાર્યો, પગાર સ્ટબ અને શેડ્યૂલ ફેરફાર, સૌથી નવું પહેલા.",
  "workforce.messages.back": "બધી વાતચીત",
  "workforce.messages.empty": "હજી કોઈ વાતચીત નથી. ઉપરના બટનથી એક શરૂ કરો.",
  "workforce.messages.emptyThread": "હજી કોઈ સંદેશ નથી. શરૂઆત કરવા માટે નમસ્તે કહો.",
  "workforce.messages.help": "તમારી ટીમ સાથે ખાનગી એક-થી-એક સંદેશ — બીજી કોઈ એપની જરૂર નથી. વાતચીતમાં ફક્ત બે વ્યક્તિ જ તે વાંચી શકે છે, ઉપરાંત વ્યવસાય માલિક, જે તેમના સ્ટોરની દેખરેખ રાખે છે.",
  "workforce.messages.new": "નવો સંદેશ",
  "workforce.messages.oversight": "માલિક દૃશ્ય",
  "workforce.messages.oversightNote": "તમે આ વાતચીત વાંચી શકો છો કારણ કે તમે આ વ્યવસાયના માલિક છો. તમે તેમાં જોડાઈ શકતા નથી.",
  "workforce.messages.owner": "વ્યવસાય માલિક",
