  "pos.square.help": "Square જોડો અને ટિલ પરનું દરેક વેચાણ તેની આઇટમ અહીં આપોઆપ સ્ટોકમાંથી બહાર કાઢે છે — દિવસના અંતે કંઈ ટાઇપ કરવાનું નથી.",
