  "plansLib.includes.recovery": "બેકઅપ કોડ અને બેકઅપ ઈમેઈલ સાથે એકાઉન્ટ પુનઃપ્રાપ્તિ",
  "plansLib.includes.offline": "તમે ફરી જોડાઓ ત્યારે સિંક થતી ઓફલાઇન સ્કેન કતાર",
