  "print.carrier.title": "તમારા વાહકનું લેબલ",
  "print.carrier.desc": "ટપાલ ખર્ચ વાહક પાસેથી ખરીદો, જેમ તમે આજે કરો છો — આ ઍપ ક્યારેય ટપાલ ખર્ચ વેચતી નથી, તેથી તમે જે ભાવ ચૂકવો છો તે હંમેશા વાહકનો પોતાનો ભાવ છે. લેબલ ફાઇલ અહીં સાચવો અને તે આ ઑર્ડર પર કાયમ રહેશે: તમારો રેકોર્ડ, કંઈ થાય તો હાથમાં.",
