  "print.carrier.pdfHint": "આ લેબલ એક PDF છે. તે તેના સાચા કદમાં ખૂલે છે — વ્યૂઅરમાંથી છાપો અને તે બરાબર 4×6 માં બહાર આવશે.",
  "print.carrier.pickOrderFirst": "ઉપર એક ઑર્ડર પસંદ કરો, પછી તેનું વાહક લેબલ અહીં સાચવો.",
  'print.carrier.pickFirstTap': "પહેલા ઉપર એક ઓર્ડર પસંદ કરો — પછી આ બટન કેરિયર લેબલ તે ઓર્ડરમાં સાચવશે.",
  "print.style.title": "દસ્તાવેજ શૈલી",
  "print.style.desc": "તમારા દસ્તાવેજોને તમારા બનાવો. આ પસંદગીઓ તમારા ઇન્વૉઇસ, રસીદ, પૅકિંગ સ્લિપ, વળતર દસ્તાવેજો, ઉત્પાદન શીટ, ગણતરી શીટ અને પિક લિસ્ટને શણગારે છે — અને તમારા વ્યવસાય માટે યાદ રાખવામાં આવે છે.",
