  "print.printedAt": "{date} ના રોજ {time} વાગ્યે છપાયું",
  "print.style.previewText": "ઝડપી ભૂરો શિયાળ આળસુ કૂતરા પરથી કૂદી જાય છે. 1234567890",
  "training.lessons.owner-shipping-labels.step1": "પ્રિન્ટ સેન્ટરમાં બંને પ્લાનમાં શિપિંગ લેબલ શૈલી છે: ગ્રાહકનો ઓર્ડર પસંદ કરો અને ખરીદદારના નામ અને સરનામાં તથા મોકલનાર તરીકે તમારા વ્યવસાય સાથે 4×6 લેબલ છાપો.",
  "training.lessons.owner-shipping-labels.step2": "આ લેબલ દરેક ગ્રાહક દસ્તાવેજની જેમ વ્હાઇટ-લેબલ છે: તેના પર ફક્ત તમારા વ્યવસાયનું નામ હોય છે — આ એપનું નામ ક્યારેય નહીં — જેથી તમારી દુકાનથી આવેલું પાર્સલ તમારી જ દુકાનથી આવ્યું લાગે.",
  "training.lessons.owner-shipping-labels.step3": "ગ્રાહકનું સરનામું તેમના છેલ્લા ઓર્ડર પછી 90 દિવસ સુધી તેમના ઓર્ડર સાથે રાખવામાં આવે છે, અને લેબલ જ્યારે ઓર્ડરનું સાચવેલું સરનામું હોય ત્યારે તેમાંથી શરૂ થાય છે; એક વખતના લેબલ માટે પ્રિન્ટ સમયે લખેલું સરનામું પાછું સાચવવામાં આવતું નથી. નામ હજી પણ ઓર્ડરમાંથી ભરાય છે જેથી લેબલ કાગળો સાથે મેળ ખાય.",
  "training.lessons.owner-shipping-labels.step4": "આ લેબલ દરેક લેબલ જેવા જ ચાર કનેક્શનથી છપાય છે — બ્લૂટૂથ, વાઇ-ફાઇ, ઇથરનેટ અને USB — અને 4×6 થર્મલ પ્રિન્ટર તેનું પ્રમાણભૂત કદ છે.",
  "training.lessons.owner-shipping-labels.step5": "તેના બદલે ટપાલ ખર્ચ વાહક પાસેથી ખરીદ્યો? આ જ વિભાગમાં તમે વાહકની લેબલ ફાઇલ — PDF, PNG કે JPG — અપલોડ કરી શકો છો અને તે ઑર્ડર પર કાયમ સાચવાયેલી રહેશે: તમારો રેકોર્ડ, કંઈ થાય તો હાથમાં. તે તેના સાચા 4×6 કદમાં છપાય છે. ઍપ ક્યારેય ટપાલ ખર્ચ વેચતી નથી, તેથી વાહકનો ભાવ એકમાત્ર ભાવ છે — અને હંમેશા સાચો ભાવ.",
  "training.lessons.owner-shipping-labels.title": "ગ્રાહક ઓર્ડર માટે શિપિંગ લેબલ",
  "training.lessons.print-shipping-label.step1": "જ્યારે ઓર્ડર મોકલવા માટે તૈયાર હોય, ત્યારે પ્રિન્ટ સેન્ટર ખોલો, શિપિંગ લેબલ શૈલી પસંદ કરો અને પછી ગ્રાહકનો ઓર્ડર પસંદ કરો. ખરીદદારનું નામ ઓર્ડરમાંથી ભરાય છે.",
  "training.lessons.print-shipping-label.step2": "પાર્સલ જે સરનામે જઈ રહ્યું છે તે તપાસો. જ્યારે ઓર્ડરમાં ગ્રાહકનું સરનામું હોય — તેમના છેલ્લા ઓર્ડર પછી 90 દિવસ સુધી રાખેલું — ત્યારે તે તમારા માટે ભરાઈ જાય છે; પ્રિન્ટ સમયે તમે લખેલું સરનામું પાછું સાચવવામાં આવતું નથી, તેથી પ્રિન્ટ કરતા પહેલા પોસ્ટકોડ અને છેલ્લી લાઇન કાળજીપૂર્વક તપાસો.",
  "training.lessons.print-shipping-label.step3": "તમારા વ્યવસાયનું નામ મોકલનાર તરીકે ઉપર છપાય છે. જો તમારું સરનામું પણ લેબલ પર જોઈતું હોય, તો તેને મોકલનારના સરનામાંના ખાનામાં લખો; જો દેખાડવું ન હોય તો ખાલી રાખો.",
  "training.lessons.print-shipping-label.step4": "4×6 લેબલ પર છાપો — થર્મલ લેબલ પ્રિન્ટર સામાન્ય પસંદગી છે — અથવા બ્રાઉઝરના પ્રિન્ટ બટનથી કોઈપણ પ્રિન્ટર પર. લેબલને પાર્સલ પર સપાટ ચોંટાડો, જ્યાં તે કિનારી પર વળે નહીં.",
  "training.lessons.print-shipping-label.step5": "જો ટપાલ ખર્ચ વાહક પાસેથી ખરીદાયો હતો, તો તેના બદલે તેમની લેબલ ફાઇલ ઑર્ડર પર સાચવો: તમારા વાહકનું લેબલ વિભાગમાં વાહકે આપેલી PDF, PNG કે JPG અપલોડ કરો. તે તમારા રેકોર્ડ તરીકે ઑર્ડર પર રહે છે અને તેના સાચા 4×6 કદમાં છપાય છે — અને જ્યારે તમે તેનો ઉપયોગ કરવાનું પસંદ કરો ત્યારે ઍપનું પોતાનું સરનામું લેબલ હંમેશા ત્યાં છે.",
  "training.lessons.print-shipping-label.title": "શિપિંગ લેબલ છાપો",
  "pos.provider.clover": "Clover",
