  "apiErrors.supportMessageTooShort": "કૃપા કરીને અમને થોડું વધુ કહો — એક કે બે વાક્યો અમને તે શોધવામાં મદદ કરે છે.",
  "apiErrors.supportRateLimited": "તમે આજે ઘણા અહેવાલો મોકલ્યા છે. કૃપા કરીને વધુ મોકલવા માટે આવતીકાલ સુધી રાહ જુઓ, જેથી દરેક અહેવાલ યોગ્ય રીતે વાંચી શકાય.",
