  "apiErrors.tooManyAttempts.tooManyWrongCodes2": "ઘણા બધા ખોટા કોડ — આ પુનઃપ્રાપ્તિ લોક છે. થોડી વાર રાહ જુઓ, પછી નવો કોડ માંગો.",
