  "training.quiz.intro": "આ પાઠ પૂરો કરવા માટે દરેક પ્રશ્નનો સાચો જવાબ આપો. તમે જેટલી વાર જોઈએ તેટલી વાર પ્રયાસ કરી શકો છો.",
