  "profile.title": "તમારો પ્રોફાઇલ ફોટો",
  "profile.ownerDesc": "તમારો ફોટો અને તમારી ટીમ તમને જે નામથી ઓળખે છે તે નામ. તમારો પોતાનો ફોટો તરત જ દેખાય છે — કોઈ મંજૂરીની જરૂર નથી.",
  "profile.memberDesc": "માલિક મંજૂર કરે પછી તમારો ફોટો તમારા નામની બાજુમાં દેખાય છે. ત્યાં સુધી, ફક્ત તમારા નામના પ્રથમ અક્ષરો દેખાય છે.",
  "profile.stateApproved": "આ તે ફોટો છે જે તમારી ટીમ જુએ છે.",
  "profile.stateNone": "તમે હજી સુધી કોઈ ફોટો ઉમેર્યો નથી.",
  "profile.statePending": "તમારો ફોટો માલિકની મંજૂરીની રાહ જોઈ રહ્યો છે. તેઓ મંજૂર ન કરે ત્યાં સુધી તે ક્યાંય દેખાશે નહીં.",
  "profile.stateChangePending": "તમારો નવો ફોટો માલિકની મંજૂરીની રાહ જોઈ રહ્યો છે. ત્યાં સુધી તમારો વર્તમાન ફોટો રહેશે.",
  "profile.choose": "ફોટો પસંદ કરો",
  "profile.change": "ફોટો બદલો",
  "profile.declinedFirst": "તમારો ફોટો મંજૂર થયો નથી. કૃપા કરીને બીજો ફોટો પસંદ કરો.",
  "profile.declinedChange": "તમારો ફોટો મંજૂર થયો નથી — પરંતુ તમારો બીજો ફોટો હજી પણ તમારી પાસે છે. જો તમે તેને બદલવા માંગતા હો, તો બીજો ફોટો અજમાવો.",
  "profile.approvedNote": "માલિકે તમારો ફોટો મંજૂર કર્યો છે.",
  "profile.toastOwnerLive": "તમારો ફોટો હવે લાઇવ છે.",
  "profile.toastSent": "મંજૂરી માટે માલિકને મોકલવામાં આવ્યો.",
  "profile.toastFailed": "તે કામ ન થયું — કૃપા કરીને ફરી પ્રયાસ કરો.",
  "profile.nameLabel": "તમારું નામ",
  "profile.nameHint": "આ નામ દરેક જગ્યાએ માલિક શબ્દની જગ્યા લે છે — તમારા ફોટાની બાજુમાં, સંદેશાઓમાં અને તમારી ટીમની સ્ક્રીન પર. માલિક તરીકે ઓળખાવા માટે તેને ખાલી છોડો.",
