  "profile.nameCleared": "તમારું નામ સાફ કરવામાં આવ્યું છે — તમે ફરીથી માલિક તરીકે ઓળખાઓ છો.",
  "profile.approvalsTitle": "તમારી મંજૂરીની રાહ જોતા ફોટા",
  "profile.approvalsDesc": "તમે મંજૂર ન કરો ત્યાં સુધી ટીમનો કોઈ ફોટો ક્યાંય દેખાતો નથી. જો તમે તેને મંજૂર ન કરો, તો તે વ્યક્તિને બીજો ફોટો પસંદ કરવાનું કહેવામાં આવે છે.",
