  "payroll.dd.viewForm": "સહી કરેલું ફોર્મ જુઓ",
  "payroll.profile.address": "ઘરનું સરનામું",
  "payroll.profile.name": "પૂરું નામ",
  "payroll.profile.noAddress": "હજી સુધી ઘરનું કોઈ સરનામું નોંધાયેલું નથી.",
  "payroll.profile.note": "આ વિગતો તમારા પગાર અને કર ફોર્મ માટે વપરાય છે, અને ફક્ત તમે જ તેને અહીં જોઈ શકો છો. જો કંઈ બદલવાની જરૂર હોય, તો માલિક અથવા તમારા મેનેજરને કહો — તેઓ જ તેને અપડેટ કરી શકે છે.",
  "payroll.profile.title": "તમારી નોંધાયેલી વિગતો",
  "payroll.stubs.print": "છાપો / ડાઉનલોડ",
  "apiErrors.invalidValue.signYourForm": "તમારા ડાયરેક્ટ ડિપોઝિટ ફોર્મ પર સહી કરવા માટે તમારું નામ લખો.",
  "apiErrors.invalidValue.chooseSignatureStyle": "સહીની શૈલી પસંદ કરો.",
  "apiErrors.invalidValue.noDdDetailsYet": "તે ટીમ સભ્યએ હજી સુધી તેમની વિગતો મોકલી નથી.",
  "training.lessons.owner-dd-setup.step5": "જે પહોંચે છે તે એક સીલ કરેલું, સહી કરેલું ફોર્મ છે: પેરોલમાં તે વ્યક્તિની હરોળમાંથી તમે તેને ખોલીને સંપૂર્ણ નંબર વાંચી શકો છો, છાપી શકો છો અથવા નકલ સાચવી શકો છો — તમે તેને ક્યારેય સંપાદિત કરી શકતા નથી. જો કોઈ નંબર ખોટો લાગે, તો ફોર્મ પાછું મોકલો: વ્યક્તિ જાતે તેને સુધારે છે અને ફરી સહી કરે છે, તેમનું સુધારેલું ફોર્મ જૂનાની જગ્યા લે છે, અને અગાઉનું ફોર્મ તેની બદલીની તારીખ સાથે રેકોર્ડમાં રહે છે.",
  "payroll.profile.ownerNote": "આ તમારી પોતાની વિગતો છે જે ફાઇલમાં છે, તમારા ખાતામાંથી. ફક્ત તમે જ અહીં તે જોઈ શકો છો — અને તે તમારી હોવાથી, બદલાય ત્યારે તમે અહીં જ તેને અપડેટ કરી શકો છો.",
  "payroll.profile.edit": "તમારી વિગતો સંપાદિત કરો",
  "payroll.profile.cancel": "રદ કરો",
  "payroll.profile.noName": "હજી સુધી કોઈ નામ નોંધાયેલું નથી.",
  "apiErrors.forbidden.businessOwnerUpdateDetails": "ફક્ત વ્યવસાયનો માલિક જ આ વિગતો અપડેટ કરી શકે છે.",
  "apiErrors.invalidValue.homeAddressThousandCharacters": "તમારું ઘરનું સરનામું 1000 અક્ષરો કે તેથી ઓછું રાખો.",
  "plans.status.foundingTester": "સ્થાપક પરીક્ષક",
  "plans.priceNoteFoundingTester": "કોઈ ચાર્જ નહીં — સ્થાપક પરીક્ષકો Business ને હંમેશા માટે મફત રાખે છે.",
  "subscribe.foundingTesterNote": "આ કાર્યક્ષેત્ર પાસે સ્થાપક પરીક્ષક તરીકે Business છે — હંમેશા માટે મફત. કોઈ કાર્ડ નહીં, કોઈ ચાર્જ નહીં, ક્યારેય નહીં.",
  "upgrade.introFoundingTester": " — એક સ્થાપક પરીક્ષક કાર્યક્ષેત્ર, હંમેશા માટે મફત અને કોઈ ચાર્જ વિના.",
  "upgrade.foundingTesterNote": "સ્થાપક પરીક્ષકો Business ને હંમેશા માટે મફત રાખે છે — અહીં બદલવા માટે કોઈ પ્લાન નથી અને રદ કરવા માટે કોઈ સબ્સ્ક્રિપ્શન નથી.",
  "apiErrors.foundingTester.alreadyListed": "તે ઇમેઇલ પહેલેથી જ સ્થાપક પરીક્ષકોની યાદીમાં છે.",
  "apiErrors.foundingTester.listFull": "સ્થાપક પરીક્ષકોની યાદી ભરેલી છે.",
