  "apiErrors.foundingTester.capWholeNumber": "મર્યાદા 1 કે તેથી વધુ પૂર્ણ સંખ્યા હોવી જોઈએ.",
  "staffLib.perm.staffClockBoard": "ઘડિયાળ બોર્ડ અને ચૂકી ગયેલા ક્લોક-આઉટ",
