  "staffLib.area.clockAccess": "ઘડિયાળ બોર્ડ અને કૉલ-ઇન",
  "staff.memberDialog.clockAccessHint": "ફક્ત મેનેજરો માટે — બે અલગ ટિક. ઘડિયાળ બોર્ડ અને ચૂકી ગયેલા ક્લોક-આઉટ આ મેનેજરને ટીમની ઘડિયાળ એન્ટ્રીઓ જોવા અને સ્ટાફ પેજ પરથી સમય એન્ટ્રીઓ સુધારવા દે છે. કૉલ-ઇન આ મેનેજરને કૉલ-ઇન વિન્ડો ખોલવા દે છે, કોઈને તેની શિફ્ટ નક્કી ન હોય ત્યારે કામ કરવા દેવું. આ ટિક સ્ટાફ માટે કંઈ કરતા નથી.",
  "workforce.clockGate.closed": "અત્યારે તમારું કામ નક્કી નથી, અને તમારા માટે કોઈ કૉલ-ઇન વિન્ડો ખુલ્લી નથી.",
  "workforce.clockGate.closedNext": "અત્યારે તમારું કામ નક્કી નથી, અને તમારા માટે કોઈ કૉલ-ઇન વિન્ડો ખુલ્લી નથી. તમારી આગલી શિફ્ટ {when} શરૂ થાય છે.",
  "workforce.callIn.openForYou": "તમને બોલાવવામાં આવ્યા છે — કોઈ શિફ્ટ આ સમયને આવરતી ન હોય તો પણ તમે હવે ક્લોક ઇન કરી શકો છો.",
  "workforce.entries.calledIn": "બોલાવ્યા",
