  "workforce.entries.missedDetail": "નક્કી {start} – {end} · ક્યારેય ક્લોક આઉટ કર્યું નથી",
  "staff.callIn.title": "કૉલ-ઇન અને ચૂકેલા ક્લોક-આઉટ",
  "staff.callIn.desc": "કોઈની શિફ્ટ નક્કી ન હોય ત્યારે તેને બોલાવો, અને ક્લોક-આઉટ ભૂલાઈ જાય ત્યારે સમય એન્ટ્રીઓ સુધારો. કૉલ-ઇન વિન્ડો તે વ્યક્તિ ક્લોક આઉટ કરે ત્યાં સુધી ખુલ્લી રહે છે.",
