  "apiErrors.clockGate.notScheduled": "અત્યારે તમારું કામ નક્કી નથી, અને તમારા માટે કોઈ કૉલ-ઇન વિન્ડો ખુલ્લી નથી.",
  "apiErrors.clockAdmin.callinsNotGranted": "ફક્ત માલિક, અથવા જે મેનેજર પર માલિકે કૉલ-ઇન માટે વિશ્વાસ મૂક્યો હોય, તે જ આ કરી શકે છે.",
  "apiErrors.clockAdmin.boardNotGranted": "ફક્ત માલિક, અથવા જે મેનેજર પર માલિકે ઘડિયાળ બોર્ડ અને ચૂકી ગયેલા ક્લોક-આઉટ માટે વિશ્વાસ મૂક્યો હોય, તે જ આ કરી શકે છે.",
  "apiErrors.clockAdmin.ownerOnlyForManager": "મેનેજરના કૉલ-ઇન અને સમય એન્ટ્રીઓ ફક્ત માલિક જ સંભાળી શકે છે.",
  "apiErrors.clockFix.outBeforeIn": "ક્લોક-આઉટનો સમય ક્લોક-ઇનના સમય પછી હોવો જોઈએ.",
  "apiErrors.clockFix.breakOutside": "વિરામના સમય ક્લોક-ઇન અને ક્લોક-આઉટ સમયની વચ્ચે હોવા જોઈએ.",
  "apiErrors.clockFix.invalidTime": "દરેક સમયને માન્ય તારીખ અને સમય તરીકે મોકલો.",
  "apiErrors.notFound.timeEntryFound": "સમય એન્ટ્રી મળી નથી.",
  "training.lessons.mgr-clock-callin.title": "કૉલ-ઇન અને ઘડિયાળ સુધારા",
  "training.lessons.mgr-clock-callin.step1": "માલિક મેનેજરને બે અલગ ટિક આપી શકે છે. કૉલ-ઇન સાથે, તમે સ્ટાફ સભ્ય માટે કૉલ-ઇન વિન્ડો ખોલી શકો છો, અને ઘડિયાળ બોર્ડ અને ચૂકી ગયેલા ક્લોક-આઉટ સાથે, તમે ટીમનું ઘડિયાળ બોર્ડ જોઈ શકો છો અને સ્ટાફ પેજ પરથી સમય એન્ટ્રીઓ સુધારી શકો છો. દરેક ટિક પોતાની રીતે કામ કરે છે — મેનેજર એક વગર બીજું રાખી શકે છે.",
  "training.lessons.mgr-clock-callin.step2": "કૉલ-ઇન વિન્ડો કોઈ વ્યક્તિને કોઈ શિફ્ટ તેને આવરતી ન હોય ત્યારે સાઇન ઇન અને ક્લોક ઇન કરવા દે છે. તેને સ્ટાફ પેજ પર, કૉલ-ઇન અને ચૂકેલા ક્લોક-આઉટ કાર્ડ પરથી ખોલો.",
  "training.lessons.mgr-clock-callin.step3": "તે વ્યક્તિ ક્લોક આઉટ કરે ત્યાં સુધી વિન્ડો ખુલ્લી રહે છે — પછી સાઇન-આઉટ પહેલાંની સામાન્ય 10-મિનિટની છૂટ આવે છે — અથવા તમે કે માલિક તેને વહેલા બંધ કરો ત્યાં સુધી. કંઈ પણ તેને જાતે બંધ કરતું નથી.",
  "training.lessons.mgr-clock-callin.step4": "જ્યારે કોઈ ક્લોક આઉટ કરવાનું ભૂલી જાય છે, ત્યારે નક્કી શિફ્ટ પૂરી થતાં જ તેની એન્ટ્રી સ્ટાફ પેજ અને પેરોલમાં ચિહ્નિત થાય છે, અને તમને અને માલિકને સૂચના મળે છે. એન્ટ્રી સુધરે ત્યાં સુધી ગણતી રહે છે.",
  "training.lessons.mgr-clock-callin.step5": "સ્ટાફ પેજ પરથી એન્ટ્રી સુધારો: ક્લોક-ઇન, ક્લોક-આઉટ અને વિરામના સમય નક્કી કરો. મેનેજર ફક્ત સ્ટાફની એન્ટ્રીઓ સુધારે છે — મેનેજરની પોતાની એન્ટ્રીઓ માલિક સુધારે છે.",
  "staffLib.perm.staffDocuments": "સ્ટાફ દસ્તાવેજો",
  "staffLib.area.documentsAccess": "સ્ટાફ દસ્તાવેજો",
  "staff.memberDialog.documentsAccessHint": "ફક્ત મેનેજરો માટે — આ ટિક સાથે, આ મેનેજર સ્ટાફ સભ્યોની દસ્તાવેજ ફાઇલો ખોલી શકે છે: દરેક વ્યક્તિ માટે રાખેલા કાગળો, જેમ કે W-4 ફોર્મ, નોકરીની અરજીઓ અને ઓળખપત્રની નકલો. પહેલા તમારી પુષ્ટિ માંગવામાં આવશે — આ ફાઇલોમાં સામાજિક સુરક્ષા નંબર અને જન્મ તારીખો હોય છે. આ ટિક સ્ટાફ માટે કંઈ કરતું નથી.",
  "staff.documentsWarning.body": "આ વ્યક્તિ તમારા સ્ટાફ સભ્યો વિશે ગુપ્ત માહિતી જોઈ શકશે, જેમાં સામાજિક સુરક્ષા નંબર અને જન્મ તારીખોનો સમાવેશ થાય છે.",
  "staff.documentsWarning.confirm": "હા, હું સમજું છું",
  "staff.documents.title": "સ્ટાફ દસ્તાવેજો",
  "staff.documents.desc": "દરેક વ્યક્તિ માટે તમે રાખેલા કાગળો — W-4 ફોર્મ, નોકરીની અરજીઓ, કર ફોર્મ, ઓળખપત્રની નકલો. ફક્ત તમે, અને જે મેનેજરને તમે સ્ટાફ દસ્તાવેજો ટિક આપો, આ ફાઇલો ખોલી શકો છો.",
