  "staff.documents.mineTitle": "મારા દસ્તાવેજો",
  "staff.documents.mineDesc": "તમારા માલિક તમારા માટે ફાઇલમાં રાખેલા કાગળો — W-4 ફોર્મ, તમારી નોકરીની અરજી, કર ફોર્મ, ઓળખપત્રની નકલો. આ તમારી પોતાની ફાઇલ છે: તમે તેમાંની કોઈપણ વસ્તુ ખોલી, ડાઉનલોડ અને છાપી શકો છો, પરંતુ અહીં કંઈ બદલી શકાતું નથી.",
