  "restaurant.emptyBody": "તમારી પહેલી રેસિપી લખો — એક સોસ, એક ડિશ, સ્ટોકની વસ્તુઓથી તમે જે કંઈ બનાવો છો — અને વેચવા તૈયાર હો ત્યારે તેને કોઈ પ્રોડક્ટ સાથે જોડો.",
