  "plansLib.businessIncludes.restaurantOps": "રેસ્ટોરન્ટ કામગીરી — ત્રણ-બાજુ મેળ સાથે સપ્લાયર ઇનવોઇસ, બગાડ નોંધ, સમાપ્તિ તારીખો અને એલર્જન કોષ્ટક",
  "plansLib.businessIncludes.restaurantDaily": "રેસ્ટોરન્ટના રોજિંદા સાધનો — તાપમાન નોંધો, ખતમ થયેલી વસ્તુઓનું બોર્ડ, તૈયારી શીટ, મેનુ વિશ્લેષણ, તફાવત અને એકાઉન્ટિંગ નિકાસ",
