  "restaurant.doorMenu": "વાનગીઓ તે કેટલી વેચાય છે અને કેટલું કમાય છે તે પ્રમાણે ક્રમમાં.",
  "restaurant.doorVariance": "શેલ્ફ પરથી શું જવું જોઈતું હતું, તેની બાજુમાં જે ખરેખર ગયું.",
  "restaurant.doorPrep": "બેચ ઉત્પાદન અને તૈયારી શીટ, પાર સ્તરોમાંથી.",
  "restaurant.doorLedger": "ખરીદી, બગાડ, સ્ટાફ ભોજન અને વપરાશ એક જ નિકાસમાં.",
  "restaurant.kitchenTitle": "એકમો અને એલર્જન",
  "restaurant.kitchenIntro": "ઉત્પાદનના એલર્જન, તેની રેસિપી લાઇનો વાપરી શકે તેવા એકમો, અને તેની શેલ્ફ લાઇફ નક્કી કરો.",
  "ops.invoices.title": "સપ્લાયર ઇનવોઇસ",
  "ops.invoices.subtitle": "દરેક સપ્લાયરે શું બિલ કર્યું, તેના ખરીદ ઓર્ડર સામે ત્રણ રીતે ચકાસાયેલું: ઓર્ડર કર્યું, મળ્યું અને ઇનવોઇસ કર્યું. જ્યારે બિલની કિંમત બદલાય, ત્યારે અહીં કિંમત ચેતવણી ખૂલે છે.",
  "ops.invoices.newButton": "નવું ઇનવોઇસ",
  "ops.invoices.newTitle": "નવું સપ્લાયર ઇનવોઇસ",
  "ops.invoices.editTitle": "સપ્લાયર ઇનવોઇસ સંપાદિત કરો",
  "ops.invoices.dialogIntro": "ઇનવોઇસ સપ્લાયરે મોકલ્યું તેમ જ દાખલ કરો. તે જે ખરીદ ઓર્ડરનું છે તે પસંદ કરવાથી સાચવતા પહેલા ત્રણ-બાજુ મેળ દેખાય છે.",
