  "storefronts.disconnectNote": "જોડાણ તોડવાથી નવું વેચાણ આવતું બંધ થઈ જાય છે. પહેલેથી નોંધાયેલું વેચાણ તમારા ઇતિહાસમાં રહે છે.",
  "storefronts.ebayDesc": "તમારા eBay સ્ટોરફ્રન્ટને એક વાર જોડો. જ્યારે કોઈ વસ્તુ eBay પર વેચાય છે, ત્યારે તેની ગણતરી અહીં જાતે જ ઘટી જાય છે, અને વેચાણ તમારી હિલચાલમાં નોંધાય છે — બરાબર જાણે તેને સ્કેન કરીને બહાર કાઢવામાં આવી હોય. વેચાણ ફક્ત એક જ દિશામાં આવે છે: eBay થી એપમાં.",
