  "storefronts.locationHint": "તમારો eBay સ્ટોક જ્યાં છે તે સ્થાન પસંદ કરો. વેચાણ પહેલા ત્યાંથી લેવામાં આવે છે.",
  "storefronts.locationLabel": "વેચાણ કપાય છે",
  "storefronts.matchingEmpty": "કંઈ પણ રાહ જોતું નથી. અત્યાર સુધીનું દરેક eBay વેચાણ જાતે જ કોઈ ઉત્પાદન સાથે મળી ગયું છે.",
  "storefronts.matchingIntro": "{count} વેચાયેલી વસ્તુ હજી સુધી કોઈ ઉત્પાદન સાથે મળી શકી નથી. દરેકને તેના ઉત્પાદન સાથે લિંક કરો અને તેનું અટકેલું વેચાણ જાતે જ નોંધાઈ જશે — રાહ જોતી વખતે કંઈ ખોવાતું નથી.",
  "storefronts.matchingTitle": "વેચાણ જેને મેળની જરૂર છે",
  "storefronts.neverChecked": "હજી સુધી તપાસ્યું નથી — તપાસ દિવસભર જાતે પણ થતી રહે છે.",
  "storefronts.notAvailableBody": "એપના માલિકે હજી સુધી eBay કીઓ ઉમેરી નથી, તેથી આ દરવાજો ખૂલી શકતો નથી. આ પૃષ્ઠ પર બાકીનું બધું તૈયાર છે — કીઓ ઉમેરાઈ જાય પછી ફરી તપાસો.",
