  "storefronts.staffNote": "માલિક અથવા મેનેજર આ જોડાણની સંભાળ રાખે છે. તમે અહીં તેની સ્થિતિ જોઈ શકો છો.",
  "storefronts.subtitle": "એક સ્ટોરફ્રન્ટને એક વાર જોડો, અને તેનું વેચાણ તમારા સ્ટોકને જાતે જ અપડેટ કરશે.",
  "storefronts.title": "સ્ટોરફ્રન્ટ જોડાણો",
  "training.lessons.owner-ebay-connect.step1": "સ્ટોરફ્રન્ટ જોડાણો ખોલો (વેચાણ જૂથમાં) અને eBay જોડો પર ટેપ કરો. તમે eBay ના પોતાના પૃષ્ઠ પર સાઇન ઇન કરો છો — એપ ક્યારેય તમારો eBay પાસવર્ડ જોતી નથી.",
  "training.lessons.owner-ebay-connect.step2": "એક eBay સ્ટોરફ્રન્ટ એક વ્યવસાય સાથે જોડાય છે — તે વ્યવસાય જેનો માલ તે સ્ટોર વેચે છે. જો તમે એક કરતાં વધુ વ્યવસાય ચલાવો છો, તો દરેક સ્ટોરને તેના પોતાના વ્યવસાય સાથે જોડો.",
  "training.lessons.owner-ebay-connect.step3": "તમારો eBay સ્ટોક જ્યાં છે તે સ્થાન પસંદ કરો, જેથી વેચાણ સાચી શેલ્ફમાંથી કપાય.",
  "training.lessons.owner-ebay-connect.step4": "ત્યારથી, વેચાણ જાતે જ આવે છે: જ્યારે કોઈ વસ્તુ eBay પર વેચાય છે, ત્યારે તેની ગણતરી અહીં ઘટી જાય છે અને વેચાણ eBay ઓર્ડર નંબર સાથે હિલચાલમાં નોંધાય છે. કંઈ પણ પાછું જતું નથી — એપ ક્યારેય તમારી eBay યાદીઓ બદલતી નથી.",
  "training.lessons.owner-ebay-connect.step5": "વેચાણ યાદી પરના SKU, UPC અથવા ISBN થી મળે છે — આ ત્રણમાંથી જે પણ યાદી ધરાવે છે. જો કોઈ વેચાણ મળી ન શકે, તો તે સ્ટોરફ્રન્ટ જોડાણો પૃષ્ઠ પર 'વેચાણ જેને મેળની જરૂર છે' હેઠળ રાહ જુએ છે: તેને એક વાર તેના ઉત્પાદન સાથે લિંક કરો, અને તે વેચાણ — અને તેના જેવું ભવિષ્યનું વેચાણ — જાતે જ નોંધાઈ જશે. 'હમણાં વેચાણ તપાસો' કોઈ પણ તાજેતરની વસ્તુ લઈ આવે છે, અને જોડાણ તોડો જોડાણ બંધ કરે છે; પહેલેથી નોંધાયેલું વેચાણ રહે છે.",
  "training.lessons.owner-ebay-connect.title": "તમારું eBay સ્ટોર જોડો",
  "training.module.storefronts": "સ્ટોરફ્રન્ટ જોડાણો",
